import{_ as o,l as s,o as e,c as i,v as t,p as l,x as r,d as c,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const E=JSON.parse('{"title":"CSP","description":"","frontmatter":{"title":"CSP","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/csp.md","filePath":"cs/csp.md","lastUpdated":1789023840000}'),h={name:"cs/csp.md"};function S(m,a,P,_,u,C){const n=s("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="csp" tabindex="-1">CSP <a class="header-anchor" href="#csp" aria-label="Permalink to &quot;CSP&quot;">​</a></h1><div class="epigraph"><p>内容安全策略用声明限制页面能加载和执行的脚本、框架与连接。它把「不小心拼进页面的字符串」从默认可执行改成默认拒绝，是 XSS 的纵深，不是许可再拼接。</p><footer>—— W3C CSP；Stamm, Sterne and Markham；对照 MDN 对指令的整理</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/xss">XSS</a>要求编码。缺口是<strong>即使漏了一处</strong>，浏览器策略仍可挡住内联脚本。本课讲 CSP 指令，不写如何绕过 CSP 的清单。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>默认允许内联与 eval 时 XSS 面大。script-src 用 nonce 或 hash 放行自己的脚本。缺口是策略与报告（report-only）的部署。</p><h3 id="nonce-要随机" tabindex="-1">nonce 要随机 <a class="header-anchor" href="#nonce-要随机" aria-label="Permalink to &quot;nonce 要随机&quot;">​</a></h3><p>固定 nonce 等于没策略。每响应须用 CSPRNG。</p><p><span class="marginnote">CSP Level 3。unsafe-inline 几乎撤销脚本保护。本课禁止绕过教程。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>列关键指令：script-src、default-src、frame-ancestors、connect-src。对照 CORS 下一课：CSP 管本页能拉什么，CORS 管外源能不能读响应。</p>',12)),(e(),l(p,null,{default:r(()=>[d(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20PAGE%5B%22%E9%A1%B5%E9%9D%A2%22%5D%20--%3E%20POL%5B%22CSP%20%E5%A3%B0%E6%98%8E%22%5D%0A%20%20POL%20--%3E%20DENY%5B%22%E6%8B%92%E7%BB%9D%E6%9C%AA%E6%8E%88%E6%9D%83%E8%84%9A%E6%9C%AC%22%5D%0A%20%20POL%20--%3E%20RPT%5B%22%E6%8A%A5%E5%91%8A%E8%BF%9D%E4%BE%8B%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>纵深：编码失败时策略仍挡一类执行。它不挡无脚本的 HTML 注入外观。CORS 下一课是读响应的另一扇门。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写绕过。CORS 下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>XSS 根治是编码；CSP 是浏览器默认拒绝。</li><li>nonce/hash 放行自己的脚本。</li><li>unsafe-inline 撤防。</li><li>下一课 CORS。</li><li>出处：W3C CSP；Stamm, Sterne and Markham。</li></ul>',8))])}const A=o(h,[["render",S]]);export{E as __pageData,A as default};
